/**
 * SimpleMetrics
 * Minimal pluggable metrics helper for RaftNode/ThreadedRaftNode.
 *
 * Interface methods consumed by the nodes:
 *  - onPropose(): void
 *  - onRejected(reason: string, meta?: object): void
 *  - onRoleChange(prev: string, next: string): void
 *
 * Consumers can poll .snapshot() to read current counters.
 */
export class SimpleMetrics {
  constructor() {
    this.proposes = 0;
    this.rejections = 0;
    this.rejectionsByReason = Object.create(null);
    this.roleChanges = {
      leader: 0,
      follower: 0,
      candidate: 0,
      transitions: [],
    };
    this.lastRejection = null;
  }

  onPropose() {
    this.proposes++;
  }

  onRejected(reason, meta) {
    this.rejections++;
    const r = String(reason || 'Unknown');
    this.rejectionsByReason[r] = (this.rejectionsByReason[r] || 0) + 1;
    this.lastRejection = { reason: r, meta: meta || null, ts: Date.now() };
  }

  onRoleChange(prev, next) {
    const p = String(prev);
    const n = String(next);
    this.roleChanges.transitions.push({ prev: p, next: n, ts: Date.now() });
    if (n === 'leader') this.roleChanges.leader++;
    else if (n === 'follower') this.roleChanges.follower++;
    else if (n === 'candidate') this.roleChanges.candidate++;
  }

  snapshot() {
    return {
      proposes: this.proposes,
      rejections: this.rejections,
      rejectionsByReason: { ...this.rejectionsByReason },
      roleChanges: {
        leader: this.roleChanges.leader,
        follower: this.roleChanges.follower,
        candidate: this.roleChanges.candidate,
        transitions: this.roleChanges.transitions.slice(),
      },
      lastRejection: this.lastRejection ? { ...this.lastRejection } : null,
    };
  }

  reset() {
    this.proposes = 0;
    this.rejections = 0;
    this.rejectionsByReason = Object.create(null);
    this.roleChanges = { leader: 0, follower: 0, candidate: 0, transitions: [] };
    this.lastRejection = null;
  }
}
